CREATE OR REPLACE FUNCTION public.guard_work_during_payout() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.cleaner_payouts WHERE work_id=OLD.id) AND COALESCE(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'This timesheet has a PayPal transfer. Check its transfer status instead.'; END IF; RETURN NEW; END $$;